function Pix(props: { art: Art; scale: number }) {
  const width = props.art.rows[0]?.length ?? 0;
  const height = props.art.rows.length;
  const rects: { x: number; y: number; fill: string }[] = [];
  props.art.rows.forEach((row, y) => {
    for (let x = 0; x < row.length; x++) {
      const fill = props.art.pal[row[x]!];
      if (fill) rects.push({ x, y, fill });
    }
  });
  return (
    <svg
      width={width * props.scale}
      height={height * props.scale}
      viewBox={`0 0 ${width} ${height}`}
      shapeRendering="crispEdges"
      aria-hidden
    >
      {rects.map((rect) => (
        <rect key={`${rect.x}-${rect.y}`} x={rect.x} y={rect.y} width="1" height="1" fill={rect.fill} />
      ))}
    </svg>
  );
}

function hexToRgb(hex: string): [number, number, number] {
  const h = hex.replace("#", "");
  return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
}

function rgbToHex(r: number, g: number, b: number): string {
  const part = (n: number) => Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, "0");
  return `#${part(r)}${part(g)}${part(b)}`;
}

function shiftHue(hex: string, degrees: number): string {
  let [r, g, b] = hexToRgb(hex).map((n) => n / 255) as [number, number, number];
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  const d = max - min;
  if (d === 0) return hex;
  const s = d / (1 - Math.abs(2 * l - 1));
  let h = 0;
  if (max === r) h = ((g - b) / d) % 6;
  else if (max === g) h = (b - r) / d + 2;
  else h = (r - g) / d + 4;
  h = (h * 60 + degrees + 360) % 360;
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = l - c / 2;
  let nr = 0;
  let ng = 0;
  let nb = 0;
  if (h < 60) [nr, ng, nb] = [c, x, 0];
  else if (h < 120) [nr, ng, nb] = [x, c, 0];
  else if (h < 180) [nr, ng, nb] = [0, c, x];
  else if (h < 240) [nr, ng, nb] = [0, x, c];
  else if (h < 300) [nr, ng, nb] = [x, 0, c];
  else [nr, ng, nb] = [c, 0, x];
  return rgbToHex((nr + m) * 255, (ng + m) * 255, (nb + m) * 255);
}

function luminance(hex: string): number {
  const [r, g, b] = hexToRgb(hex);
  return r * 0.3 + g * 0.59 + b * 0.11;
}

function paint(art: Art, rarity: Rarity | "ghost"): Art {
  if (rarity === "N") return art;
  if (rarity === "ghost") {
    const pal: Record<string, string> = {};
    for (const key of Object.keys(art.pal)) pal[key] = key === "o" ? "#07080c" : "#2a2a2a";
    return { pal, rows: art.rows };
  }
  const accent = Object.entries(art.pal)
    .filter(([key]) => key !== "o")
    .sort((a, b) => luminance(b[1]) - luminance(a[1]))[0]?.[0];
  if (rarity === "UR") {
    const pal: Record<string, string> = {};
    for (const [key, color] of Object.entries(art.pal)) {
      pal[key] = key === accent ? color : "#0c0c0c";
    }
    return { pal, rows: art.rows };
  }
  const hue = rarity === "R" ? 48 : rarity === "SR" ? 150 : 210;
  const pal: Record<string, string> = {};
  for (const [key, color] of Object.entries(art.pal)) {
    pal[key] = key === "o" ? color : shiftHue(color, hue);
  }
  if (rarity === "SSR") {
    return { pal, rows: art.rows.map((row) => [...row].reverse().join("")) };
  }
  return { pal, rows: art.rows };
}

