const SKINS: Partial<Record<number, Record<Rarity, Art>>> = {
  1: BUGS,
  2: SHADES,
  3: DRYADS,
  4: CRABS,
  5: OWLS,
  6: JESTERS,
  7: LANCES,
  8: CASTLES,
  9: MOONS,
  10: FROGS,
};

function eyesOnly(art: Art): Art {
  const accent = Object.entries(art.pal)
    .filter(([key]) => key !== "o")
    .sort((a, b) => luminance(b[1]) - luminance(a[1]))[0]?.[0];
  const pal: Record<string, string> = {};
  if (accent) pal[accent] = art.pal[accent]!;
  return { pal, rows: art.rows };
}

function litEyes(art: Art): Art {
  const pal: Record<string, string> = {};
  for (const key of ["e", "w", "j", "k", "f"]) {
    if (art.pal[key]) pal[key] = art.pal[key]!;
  }
  return { pal, rows: art.rows };
}

const UR_ART: Record<number, string> = {
  1: "/ur/1.png",
  2: "/ur/2.png",
  3: "/ur/3.png",
  4: "/ur/4.png",
  5: "/ur/5.png",
  6: "/ur/6.png",
  7: "/ur/7.png",
  8: "/ur/8.png",
  9: "/ur/9.png",
  10: "/ur/10.png",
};

export function Monster(props: { id: number; scale?: number; open?: boolean; rarity?: Rarity | "ghost"; eyes?: boolean }) {
  const rarity = props.rarity ?? "N";
  const skins = SKINS[props.id];
  const base = skins
    ? skins.N
    : props.open && ALT[props.id]
      ? ALT[props.id]!
      : MONSTERS[props.id];
  if (!base) return null;
  const skin = rarity === "ghost" ? "" : ` skin-${rarity}`;
  if (rarity === "UR" && UR_ART[props.id]) {
    return (
      <span className={`pixel-mon idle-${props.id}${props.open ? " is-open" : ""}${skin}`}>
        <img className="ur-art" src={UR_ART[props.id]} alt="" />
        <span className="idle-bit" />
      </span>
    );
  }
  const art = skins && rarity !== "ghost"
    ? props.eyes ? litEyes(skins.N) : skins[rarity]
    : props.eyes
      ? eyesOnly(base)
      : paint(base, rarity);
  const asked = props.scale ?? 3;
  const scale = skins ? (asked >= 4 ? 2 : 1) : asked;
  return (
    <span className={`pixel-mon idle-${props.id}${props.open ? " is-open" : ""}${skin}`}>
      <Pix art={art} scale={scale} />
      <span className="idle-bit" />
    </span>
  );
}

export function RoleIcon(props: { id: number }) {
  const art = ICONS[props.id];
  if (!art) return null;
  return <Pix art={art} scale={2} />;
}

export function PoisonDrop() {
  return <Pix art={ICONS[1]!} scale={2} />;
}

export function PixelBack(props: { scale?: number }) {
  return <Pix art={BACK} scale={props.scale ?? 3} />;
}
